    topupForm.onsubmit=async e=>{e.preventDefault();const guardian=topupForm.elements.guardianConsent;if(!guardian.checked){setTopupFeedback('Bạn cần xác nhận rằng nếu dưới 18 tuổi thì đã có sự đồng ý của cha mẹ/người giám hộ.',true);guardian.focus();return}if(!captchaToken){setTopupFeedback('Chưa hoàn tất Cloudflare Turnstile. Hãy chờ xác minh xong rồi bấm tạo QR.',true);qs('#teo-topup-captcha')?.scrollIntoView({behavior:'smooth',block:'center'});return}const d=Object.fromEntries(new FormData(topupForm));d.guardianConsent=true;d.amountVnd=Number(d.amountVnd);d.turnstileToken=captchaToken;const btn=topupForm.querySelector('button[type="submit"]');btn.disabled=true;setTopupFeedback('Đang tạo đơn nạp tiền…');try{const x=await request('/api/account/topups/create',{method:'POST',body:JSON.stringify(d)});renderTopupOrder(x.topup,qs('#teoTopupResult'));setTopupFeedback('Đã tạo QR. Chỉ chuyển đúng số tiền và nội dung của đơn này.')}catch(err){const code=err.data?.error;const message=code==='TURNSTILE_REQUIRED'?'Cloudflare từ chối xác minh. Hãy hoàn thành lại thử thách rồi thử lại.':code==='PAYMENT_NOT_CONFIGURED'?'Chuyển khoản đang tạm lỗi cấu hình thanh toán. Vui lòng báo Admin TeoStudio.':err.message||'Không tạo được đơn nạp tiền.';setTopupFeedback(message,true);await renderCaptcha('#teo-topup-captcha')}finally{btn.disabled=false}};
    let cardRates={},cardApiReady=false;try{const r=await request('/api/card-rates');cardRates=r.config?.providers||{};cardApiReady=!!r.topupApiConfigured;}catch{}if(!cardApiReady){qs('#teoCardTopupResult').innerHTML='<p class="teo-error">Nạp thẻ đang tạm khóa: máy chủ chưa có Partner ID/Key hoặc chưa bật đối tác. Bạn có thể chọn chuyển khoản.</p>';qs('#teoCardTopupForm button[type="submit"]').disabled=true;}

    const telco=qs('#teoCardTelco'),amount=qs('#teoCardAmount'),estimate=qs('#teoCardEstimate');const moneyV=n=>money(n);const refreshAmounts=()=>{const item=cardRates[telco.value];const rows=Object.entries(item?.rates||{}).filter(([k,v])=>Number(k)>=1000&&Number(k)<=10000000&&Number(k)%1000===0&&Number.isFinite(Number(v?.providerFee))).sort((a,b)=>Number(a[0])-Number(b[0]));amount.innerHTML='<option value="">Chọn mệnh giá</option>'+rows.map(([n])=>`<option value="${Number(n)}">${moneyV(n)}</option>`).join('');refreshCardEstimate()};const refreshCardEstimate=()=>{const item=cardRates[telco.value],rate=item?.rates?.[amount.value],fee=Number(rate?.providerFee);if(!item?.enabled||!Number.isFinite(fee)){estimate.textContent='Chọn nhà mạng và mệnh giá có trong bảng phí API.';return}const received=Math.floor(Number(amount.value)*(1-fee/100));estimate.textContent=`Phí nhà cung cấp ${fee.toFixed(2)}% · Dự kiến Merchant nhận: ${moneyV(received)}. Ví chỉ cộng amount thực nhận khi nhà cung cấp xác nhận.`};
    telco.innerHTML='<option value="">Chọn nhà mạng</option>'+Object.entries(cardRates).filter(([key,v])=>v?.enabled&&Object.keys(v.rates||{}).length).map(([key,v])=>`<option value="${esc(key)}">${esc(v.name||key)}</option>`).join('');telco.addEventListener('change',refreshAmounts);amount.addEventListener('change',refreshCardEstimate);refreshAmounts();
    qs('#teoCardTopupForm').onsubmit=async e=>{e.preventDefault();if(!cardApiReady)return;const d=Object.fromEntries(new FormData(e.target));d.guardianConsent=e.target.elements.guardianConsent.checked===true;d.amountVnd=Number(d.amountVnd);d.turnstileToken=captchaToken;const btn=e.target.querySelector('button');btn.disabled=true;try{const x=await request('/api/account/card-topups',{method:'POST',body:JSON.stringify(d)});const out=qs('#teoCardTopupResult');out.innerHTML=`<p class="teo-warning">${esc(x.message||'Đã tiếp nhận thẻ.')}</p><p>Mã giao dịch: <code>${esc(x.topup?.id||'')}</code> · Trạng thái: <b>${esc(x.topup?.status||'pending')}</b></p>${x.topup?.creditedVnd?`<p class="teo-verified">Đã cộng ${money(x.topup.creditedVnd)} vào ví.</p>`:''}`;if(x.topup?.id&&x.topup?.status!=='success'){const id=x.topup.id;let attempts=0;if(topupTimer)clearInterval(topupTimer);topupTimer=setInterval(async()=>{attempts++;try{const status=await request('/api/account/card-topups/'+encodeURIComponent(id));out.innerHTML=`<p class="teo-warning">Trạng thái thẻ: ${esc(status.topup.status)}</p><p>Mã giao dịch: <code>${esc(id)}</code></p>${status.topup.status==='success'?`<p class="teo-verified">Đã cộng ${money(status.topup.creditedVnd)} vào ví.</p>`:''}${status.topup.message?`<p class="teo-error">${esc(status.topup.message)}</p>`:''}`;if(['success','failed'].includes(status.topup.status)||attempts>=24){clearInterval(topupTimer);topupTimer=null;if(status.topup.status==='success')await renderProfile();}}catch{}},5000);}if(x.topup?.status==='success')await renderProfile();}catch(err){qs('#teoCardTopupResult').textContent=err.message;await renderCaptcha('#teo-card-captcha')}finally{btn.disabled=false}};
